puts "On va compter le nombre d'heures de travail à THP" # Cette ligne est faite pour afficher un message
puts "Travail : #{10 * 5 * 11}" # Sur cette deuxième ligne il y a une multiplication et affichage de résultat final
puts "En minutes ça fait : #{10 * 5 * 11 * 60}" #Pour cette ligne le nombre d'heures de travail est converti et affiché en minutes
puts "Et en secondes ?" # Ici il affiche le message et en secondes
puts 10 * 5 * 11 * 60 * 60 #Ici le code permet de faire des multiplications et d'afficher le temps de travail en secondes
puts "Est-ce que c'est vrai que 3 + 2 < 5 - 7 ?" #ici il affiche une question à savoir si 3+2 est supérieur à 5-7
puts 3 + 2 < 5 - 7 #Ici il affiche la réponse à la question précédente
puts "Ça fait combien 3 + 2 ? #{3 + 2}" # Il affiche une demande à savoir si le résultat de l'opération 3+2 est 5
puts "Ça fait combien 5 - 7 ? #{5 - 7}" # Il affiche une demande à savoir si le résultat de l'opération 5-7 est -2
puts "Ok, c'est faux alors!" # le code affiche un message  
puts "C'est drôle ça, faisons-en plus :" #Il affiche un message d'invitation 
puts "Est-ce que 5 est plus grand que -2 ? #{5 > -2}" #Le code affiche une question et donne la réponse en faisant la comparaison
puts "Est-ce que 5 est supérieur ou égal à -2 ? #{5 >= -2}" #Le code affiche une question de supériorité entre 5 et -2 ainsi que la réponse en effectuant la comparaison
puts "Est-ce que 5 est inférieur ou égal à -2 ? #{5 >= -2}" ##Le code affiche une question d'infériorité entre 5 et -2 ainsi que la réponse en effectuant la comparaison
